export const COMPREHENSIONS: Comprehension[] = RAW.map(([title, kind, text, questions, [q, points], creative, essay], i) => ({
  id: i + 1,
  title,
  kind,
  text,
  questions,
  open: { q, points },
  creative,
  essay,
}));

export const comprehensionById = (id: number) => COMPREHENSIONS.find((c) => c.id === id);
